contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum, uint anotherMinSum) public payable {
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumRevertedAgain;
        c.SetMinSum(anotherMinSum); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinSumRevertedAgain = true;
        } else {
            setMinSumRevertedAgain = false;
        }

        assert(setMinSumReverted && setMinSumRevertedAgain);
    }

    receive() external payable {}
}

