pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 newMinSum, uint256 anotherMinSum) internal {
        try c.Initialized() {} catch { return; }
        bool setMinSumReverted;
        try c.SetMinSum(newMinSum) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }
        try c.Initialized() {} catch { return; }
        bool setMinSumRevertedAgain;
        try c.SetMinSum(anotherMinSum) {
            setMinSumRevertedAgain = false;
        } catch {
            setMinSumRevertedAgain = true;
        }
        assertTrue(setMinSumReverted && setMinSumRevertedAgain);
    }

    function testFuzz_run(uint256 newMinSum, uint256 anotherMinSum) public {
        _run(newMinSum, anotherMinSum);
    }

    receive() external payable {}
}
